"""RoboPaint stroke-copy execution record. Public camera/proprioception API only."""
import sys, os, json, time, math
sys.path.insert(0,'/opt/tools')
import numpy as np
from PIL import Image
from rcb_client import Robot
r=Robot()
spec=r.spec()
initial=json.load(open('/app/output/initial_meta.json'))
quat=np.array(initial['proprio']['now'][10:14])
pose=np.array(initial['proprio']['now'][7:14])
seq=0

def send(a,dt=.05,cameras=None,tag='motion'):
    global pose,seq
    a=np.asarray(a,float)
    for start in range(0,len(a),180):
        chunk=a[start:start+180]
        before=r.status()
        try:
            o=r.submit('ee_pose',chunk,dt=dt,cameras=cameras or [],video='none',note=tag)
        except Exception:
            status=r.wait_ready()
            if status['calls']==before['calls']: o=r.submit('ee_pose',chunk,dt=dt,cameras=cameras or [],video='none',note=tag)
            else:
                o=r.get_obs(cameras=cameras or [])
        seq+=1
        open(f'/app/output/call_{seq:04d}.json','w').write(json.dumps(o.meta))
        pose=np.asarray(o.meta['proprio']['now'][7:14])
        if o.meta.get('plan'): print('plan',str(o.meta['plan'])[:600],flush=True)
        if o.done: raise RuntimeError('Episode over')
    return o

def path(points,speed=.08,hold=.25):
    p0=pose.copy(); a=[]
    for p in points:
        p=np.r_[p,quat] if len(p)==3 else np.asarray(p)
        n=max(1,int(np.ceil(np.linalg.norm(p[:3]-p0[:3])/speed/.05)))
        for t in range(1,n+1): a.append(p0+(p-p0)*t/n)
        p0=p
    a.extend([p0.copy()]*int(hold/.05))
    return send(a)

def observe(name,cams=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=False):
    o=r.get_obs(cameras=cams,depth=depth)
    for c,im in o.last.items(): Image.fromarray(im).save(f'/app/output/{name}_{c}.png')
    if depth:
        for c,im in o.last_depth.items(): np.save(f'/app/output/{name}_{c}_depth.npy',im)
    open(f'/app/output/{name}_meta.json','w').write(json.dumps(o.meta))
    print(name,'pose',pose,'left',o.meta['time_left_s'],flush=True)
    return o

if __name__=='__main__':
    print('READY',r.status(),flush=True)
    for line in sys.stdin:
        try:
            command=json.loads(line)
            exec(command,globals())
            print('COMMAND_DONE',flush=True)
        except Exception as e:
            import traceback; traceback.print_exc()
