   y,x=np.where(g);p=np.stack([nearest[0,y,x],nearest[1,y,x]],axis=1)
   # One projected centre per ~0.9 mm cell.
   bins=p//4;_,keep=np.unique(bins,axis=0,return_index=True);p=p[keep]
   if len(p)>600:p=p[::int(np.ceil(len(p)/600))]
